function redirect(where) {
  location.href = where;
}

function redirect_banner(where, name, header) {
  // alert(name);
  location.href = where;

  window.dataLayer = window.dataLayer || [];
  window.dataLayer.push({
    event: "cta_click",
    cta_name: name,
    cta_position: "card",
    cta_header: header,
    cta_category: "Check Whats New!",
  });
}

function redirect_blog(where, name, header) {
  //alert(name);
  location.href = where;

  window.dataLayer = window.dataLayer || [];
  window.dataLayer.push({
    event: "cta_click",
    cta_name: header,
    cta_position: "card",
    cta_header: "NA",
    cta_category: "Blogs",
  });
}

