function youtube_popup() {
  setTimeout(function () {
    $(".popup-load").magnificPopup({
      type: "iframe",
      gallery: {
        enabled: true,
      },
    });
    $(".img-popup").magnificPopup({
      type: "image",
      gallery: {
        enabled: true,
      },
    });

    $(
      ".popup-youtube, .popup-youtube-left, .popup-vimeo, .popup-gmaps"
    ).magnificPopup({
      type: "iframe",
      mainClass: "mfp-fade",
      removalDelay: 160,
      preloader: false,
      fixedContentPos: false,
    });
  }, 500);
}

body.script:
function initEmbeddedMessaging() {
  try {
    embeddedservice_bootstrap.settings.language = 'en_US'; // For example, enter 'en' or 'en-US'
    embeddedservice_bootstrap.settings.shouldShowParticipantChgEvntInConvHist = false;
    //-------Listen for the embedded messaging readiness event---------------
    window.addEventListener("onEmbeddedMessagingReady", () => {
      console.log("Inside Prechat API!");

      embeddedservice_bootstrap.userVerificationAPI
        .clearSession(true)
        .then(() => {
          console.log("Messaging session cleared successfully.");
        })
        .catch((error) => {
          console.error("Failed to clear messaging session:", error);
        })
        .finally(() => {
          console.log("Session clear attempt completed.");
        });

      // Set hidden pre-chat fields dynamically
      embeddedservice_bootstrap.prechatAPI.setHiddenPrechatFields({
        "chatreq": ""
        // Add more fields as needed
      });
    });
    //---------------------------------------------------------------------

    let agentclose = false;

    window.addEventListener("onEmbeddedMessagingConversationParticipantChanged", (event) => {

      console.log("onEmbeddedMessagingConversationParticipantChanged.");

      const entryPayload = event.detail.conversationEntry.entryPayload;
      const entry = JSON.parse(entryPayload);

      let role = entry.entries[0].participant.role;
      let operation = entry.entries[0].operation;
      if (role == 'Agent' && operation == 'remove') {
        agentclose = true;
      }
      console.log("agentclose.", agentclose);
    });

    window.addEventListener("onEmbeddedMessagingConversationClosed", (event) => {
      console.log("onEmbeddedMessagingConversationClosed.");

      if (agentclose == true) {
        agentclose = false;
      } else {
        embeddedservice_bootstrap.userVerificationAPI
          .clearSession(true)
          .then(() => {
            console.log("Messaging session cleared successfully.");
          })
          .catch((error) => {
            console.error("Failed to clear messaging session:", error);
          })
          .finally(() => {
            console.log("Session clear attempt completed.");
          });
      }
    });
    //---------------------------------------------------------------------
    window.addEventListener("onEmbeddedMessagingSessionStatusUpdate", (event) => {
      console.log("onEmbeddedMessagingSessionStatusUpdate.");
      const entryPayload = event.detail.conversationEntry.entryPayload;
      const entry = JSON.parse(entryPayload);
      if (entry.entryType === "SessionStatusChanged") {
        if (entry.sessionStatus === "Ended") {
          if (entry.sessionEndedByRole === 'Agent') {
            agentclose = true;
          }
        }
      }
    });
    //---------------------------------------------------------------------

    embeddedservice_bootstrap.init(
      '00D2w000008TDq8',
      'SFDC_Test_ESD',
      'https://sbicapsec.my.site.com/ESWSFDCTestESD1762866056191',
      {
        scrt2URL: 'https://sbicapsec.my.salesforce-scrt.com'
      }
    );
  } catch (err) {
    console.error('Error loading Embedded Messaging: ', err);
  }
};
